import React from 'react';
import './ExtractedDetails.css';

/**
 * Component for showing parsed resume information such as skills, experience, and contact details.
 */
const ExtractedDetails = ({ analysisData }) => {
  const structuredInfo = analysisData?.structuredInformation || analysisData?.structured_information || analysisData?.structuredData || {};

  const renderList = (value) => {
    if (!Array.isArray(value) || value.length === 0) {
      return <p>No data extracted.</p>;
    }

    return (
      <ul>
        {value.map((item, index) => (
          <li key={`${item}-${index}`}>{item}</li>
        ))}
      </ul>
    );
  };

  return (
    <div className="extracted-details">
      <h2>Extracted Details</h2>
      {analysisData ? (
        <div className="extracted-details__grid">
          <div>
            <h3>Contact</h3>
            <p><strong>Name:</strong> {structuredInfo.name || 'Not extracted'}</p>
            <p><strong>Email:</strong> {structuredInfo.email || 'Not extracted'}</p>
            <p><strong>Phone:</strong> {structuredInfo.phone_number || 'Not extracted'}</p>
          </div>
          <div>
            <h3>Skills</h3>
            {renderList(structuredInfo.skills)}
          </div>
          <div>
            <h3>Education</h3>
            {renderList(structuredInfo.education)}
          </div>
          <div>
            <h3>Projects</h3>
            {renderList(structuredInfo.projects)}
          </div>
          <div>
            <h3>Experience</h3>
            {renderList(structuredInfo.experience)}
          </div>
          <div>
            <h3>Certifications</h3>
            {renderList(structuredInfo.certifications)}
          </div>
          <div>
            <h3>Extracurricular</h3>
            {renderList(structuredInfo.extracurricular || structuredInfo.extra_curricular)}
          </div>
        </div>
      ) : (
        <p className="extracted-details__empty">Parsed information from the AI service will be displayed here after analysis completes.</p>
      )}
    </div>
  );
};

export default ExtractedDetails;
